// src/components/utils.jsx
function metadataObjectToState(metadata, data) {
  if (!metadata.outputs) return null;
  return Object.fromEntries(metadata.outputs.map(
    (output) => [
      output.key,
      (data && data[output.key]) ?? output.initialValue
    ]
  ));
}

